from itertools import permutations


def largest_number(nums):
    best = None
    for perm in permutations(nums):
        candidate = "".join(map(str, perm))
        if best is None or (candidate > best if len(candidate) == len(best) else len(candidate) > len(best)):
            if best is None or int(candidate) > int(best):
                best = candidate

    if best[0] == '0':
        return "0"
    return best


if __name__ == "__main__":
    print(largest_number([10, 2]))
    print(largest_number([3, 30, 34, 5, 9]))

