import java.util.*;

public class Main {
    static String bestSoFar;

    static void permute(List<Integer> nums, List<Integer> current, boolean[] used) {
        if (current.size() == nums.size()) {
            StringBuilder sb = new StringBuilder();
            for (int n : current) sb.append(n);
            String candidate = sb.toString();
            if (bestSoFar == null || new java.math.BigInteger(candidate).compareTo(new java.math.BigInteger(bestSoFar)) > 0) {
                bestSoFar = candidate;
            }
            return;
        }
        for (int i = 0; i < nums.size(); i++) {
            if (used[i]) continue;
            used[i] = true;
            current.add(nums.get(i));
            permute(nums, current, used);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }

    static String largestNumber(int[] nums) {
        List<Integer> list = new ArrayList<>();
        for (int n : nums) list.add(n);
        bestSoFar = null;
        permute(list, new ArrayList<>(), new boolean[list.size()]);
        if (bestSoFar.charAt(0) == '0') return "0";
        return bestSoFar;
    }

    public static void main(String[] args) {
        System.out.println(largestNumber(new int[]{10, 2}));
        System.out.println(largestNumber(new int[]{3, 30, 34, 5, 9}));
    }
}

