from functools import cmp_to_key


def largest_number(nums):
    strs = [str(n) for n in nums]

    def compare(a, b):
        if a + b > b + a:
            return -1
        elif a + b < b + a:
            return 1
        return 0

    strs.sort(key=cmp_to_key(compare))

    if strs[0] == '0':
        return "0"
    return "".join(strs)


if __name__ == "__main__":
    print(largest_number([10, 2]))
    print(largest_number([3, 30, 34, 5, 9]))

