#include <bits/stdc++.h>
using namespace std;

string largestNumber(vector<int>& nums) {
    vector<string> strs;
    for (int n : nums) strs.push_back(to_string(n));

    sort(strs.begin(), strs.end(), [](const string& a, const string& b) {
        return a + b > b + a;
    });

    if (strs[0] == "0") return "0";

    string result;
    for (const string& s : strs) result += s;
    return result;
}

int main() {
    vector<int> nums1 = {10, 2};
    cout << largestNumber(nums1) << endl;
    vector<int> nums2 = {3, 30, 34, 5, 9};
    cout << largestNumber(nums2) << endl;
    return 0;
}
